// 「能力检测藏在**同文件的辅助函数**里」—— 正则看不见它。
//
// 实测病例（`dshmarket`，`certainty: certain`、`severity: feature-dead`）：
//
//   function canRegister(service, ctx) {
//     if (typeof service.register === 'function') return true;   // ← 检测在这
//     logger?.warn('…the market keeps its composed configuration… (#677)');
//     return false;
//   }
//   if (!canRegister(scoped.settings, scoped)) return;   // ← 调用点守住了
//   scoped.settings.register(MARKET_SETTINGS_NS, z.object({}), { base: {} });
//
// 工具报「功能失效 / 设置页会消失」，而作者**早就兜住了**，还写清了降级行为、留了 issue 编号。
// **事实对了（方法确实不在运行时里），推断错了。** 这是 `certain` 级声明上的一条假阳性。
//
// 判据故意很窄：同文件里的函数，形参被 `typeof <参数>.<方法> === "function"` 检查过，
// 而调用点前 400 字符内紧邻一句 `if (!<那个函数>(…))`。
function canUse(service) {
  if (typeof service.doesNotExist === 'function') return true;
  return false;
}
export function apply(ctx) {
  const s = ctx.get('settings');
  if (!canUse(s)) return;
  s.doesNotExist('ns', {});
}
